1	// SPDX-FileCopyrightText: Copyright (c) 2024-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
2	// SPDX-License-Identifier: Apache-2.0
3	
4	//! The entrypoint module provides tools to build a Dynamo runner.
5	//! - Create an EngineConfig of the engine (potentially auto-discovered) to execute
6	//! - Connect it to an Input
7	
8	pub mod input;
9	pub use input::{PreprocessedRouting, build_preprocessed_routing, http::HttpFrontend};
10	
11	use std::future::Future;
12	use std::pin::Pin;
13	use std::sync::Arc;
14	
15	use dynamo_kv_router::{PrefillLoadEstimator, config::KvRouterConfig};
16	use dynamo_runtime::{discovery::ModelCardInstanceId, pipeline::RouterMode};
17	use serde::{Deserialize, Serialize};
18	
19	use crate::{
20	    backend::ExecutionContext, discovery::LoadThresholdConfig, engines::StreamingEngine,
21	    local_model::LocalModel, model_card::ModelDeploymentCard,
22	    types::openai::chat_completions::OpenAIChatCompletionsStreamingEngine,
23	};
24	
25	/// Callback type for chat engine factory (async)
26	pub type PrefillRoutedEngine = dynamo_runtime::pipeline::ServiceEngine<
27	    dynamo_runtime::pipeline::SingleIn<crate::protocols::common::preprocessor::PreprocessedRequest>,
28	    dynamo_runtime::pipeline::ManyOut<
29	        crate::types::Annotated<crate::protocols::common::llm_backend::LLMEngineOutput>,
30	    >,
31	>;
32	
